CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, recovery_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT 'My research', is_guest boolean NOT NULL DEFAULT true, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(workspace_id uuid REFERENCES workspaces ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE, role text NOT NULL DEFAULT 'owner', PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE,csrf_token text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,name text NOT NULL,description text NOT NULL DEFAULT '',audience text NOT NULL DEFAULT '',objectives jsonb NOT NULL DEFAULT '[]',assumptions jsonb NOT NULL DEFAULT '[]',questions jsonb NOT NULL DEFAULT '[]',strategy text NOT NULL DEFAULT '',success_criteria jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','closed')),public_token text UNIQUE NOT NULL,duration_minutes integer NOT NULL DEFAULT 5 CHECK(duration_minutes BETWEEN 2 AND 20),max_participants integer NOT NULL DEFAULT 12 CHECK(max_participants BETWEEN 1 AND 50),style text NOT NULL DEFAULT 'conversational',is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS campaigns_workspace_idx ON campaigns(workspace_id,created_at DESC);
CREATE TABLE IF NOT EXISTS interviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES campaigns ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,participant_label text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('starting','active','completed','withdrawn','failed')),token_hash text UNIQUE NOT NULL,consent_at timestamptz NOT NULL DEFAULT now(),consent_version text NOT NULL DEFAULT '2026-11-15',started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,duration_seconds integer NOT NULL DEFAULT 0,analysis jsonb,turn_count integer NOT NULL DEFAULT 0,turn_locked_at timestamptz);
CREATE INDEX IF NOT EXISTS interviews_campaign_idx ON interviews(campaign_id,started_at DESC);
CREATE INDEX IF NOT EXISTS interviews_workspace_idx ON interviews(workspace_id,status);
CREATE TABLE IF NOT EXISTS consent_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),interview_id uuid NOT NULL REFERENCES interviews ON DELETE CASCADE,version text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now(),withdrawn_at timestamptz);
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),interview_id uuid NOT NULL REFERENCES interviews ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('user','assistant')),text text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_interview_idx ON messages(interview_id,created_at);
CREATE INDEX IF NOT EXISTS messages_search_idx ON messages USING gin(to_tsvector('english',text));
CREATE TABLE IF NOT EXISTS turn_requests(interview_id uuid REFERENCES interviews ON DELETE CASCADE,request_id text NOT NULL,status text NOT NULL DEFAULT 'processing',user_message_id uuid REFERENCES messages ON DELETE CASCADE,response jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(interview_id,request_id));
CREATE TABLE IF NOT EXISTS speech_cache(message_id uuid PRIMARY KEY REFERENCES messages ON DELETE CASCADE,audio bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,campaign_id uuid REFERENCES campaigns ON DELETE CASCADE,interview_id uuid REFERENCES interviews ON DELETE CASCADE,agent text NOT NULL,status text NOT NULL,input jsonb,output jsonb,summary text,error text,attempt integer NOT NULL DEFAULT 1,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX IF NOT EXISTS agent_runs_workspace_idx ON agent_runs(workspace_id,started_at DESC);
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,campaign_id uuid NOT NULL REFERENCES campaigns ON DELETE CASCADE,interview_id uuid REFERENCES interviews ON DELETE CASCADE,kind text NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,run_after timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now(),unique_key text UNIQUE NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_pending_idx ON jobs(status,run_after);
CREATE TABLE IF NOT EXISTS insights(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid UNIQUE NOT NULL REFERENCES campaigns ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assistant_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,campaign_id uuid REFERENCES campaigns ON DELETE CASCADE,question text NOT NULL,answer text NOT NULL,evidence jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid UNIQUE NOT NULL REFERENCES campaigns ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,public_token_hash text UNIQUE,shared_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces ON DELETE CASCADE,kind text NOT NULL,model text,units bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS usage_daily_idx ON usage_records(created_at,kind);
CREATE TABLE IF NOT EXISTS rate_buckets(key text PRIMARY KEY,count integer NOT NULL DEFAULT 0,resets_at timestamptz NOT NULL);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
ALTER TABLE turn_requests ADD COLUMN IF NOT EXISTS user_message_id uuid REFERENCES messages ON DELETE CASCADE;
INSERT INTO schema_migrations(version) VALUES(2) ON CONFLICT DO NOTHING;
